import { useState } from "react";
import { useRouter } from "next/navigation";

export default function LoginPage() {
  const router = useRouter();

  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [loading, setLoading] = useState(false);

  async function handleLogin(e: React.FormEvent) {
    e.preventDefault();

    setLoading(true);

    try {
      const response = await fetch("/api/login", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          email,
          password,
        }),
      });

      const data = await response.json();

      if (!response.ok) {
        alert(data.message);
        return;
      }

      console.log(data.business);
      router.push("/dashboard");
    } catch (err) {
      console.error(err);
      alert("Something went wrong.");
    } finally {
      setLoading(false);
    }
  }

  return (
    <main className="min-h-screen flex items-center justify-center bg-white p-6">
      <form
        onSubmit={handleLogin}
        className="w-full max-w-md border rounded-xl p-6 shadow"
      >
        <h1 className="text-3xl font-bold text-center mb-6">
          Login to Pulse
        </h1>

        <input
          type="email"
          placeholder="Business Email"
          className="w-full border rounded-lg p-3 mb-4"
          value={email}
          onChange={(e) => setEmail(e.target.value)}
          required
        />

        <input
          type="password"
          placeholder="Password"
          className="w-full border rounded-lg p-3 mb-6"
          value={password}
          onChange={(e) => setPassword(e.target.value)}
          required
        />

        <button
          type="submit"
          disabled={loading}
          className="w-full bg-black text-white rounded-lg p-3"
        >
          {loading ? "Logging in..." : "Login"}
        </button>
      </form>
    </main>
  );
}"use client";

import { Eye, EyeOff } from "lucide-react";
import { businessTypes } from "../components/BusinessTypes";
import { useState, useRef, useEffect } from "react";
import Logo from "../components/Logo";

export default function Signup() {
  const dropdownRef = useRef<HTMLDivElement>(null);

  const [showPassword, setShowPassword] = useState(false);
  const [showConfirmPassword, setShowConfirmPassword] = useState(false);
  const [isTypingBusiness, setIsTypingBusiness] = useState(false);
  const [showBusinessList, setShowBusinessList] = useState(false);

  const [businessType, setbusinessType] = useState("");
  const [password, setPassword] = useState("");
  const [confirmPassword, setConfirmPassword] = useState("");
  const [businessName, setBusinessName] = useState("");
  const [tel, setTel] = useState("");
  const [email, setEmail] = useState("");

  const [message, setMessage] = useState("");
  const [successMessage, setSuccessMessage] = useState("");
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    function handleClickOutside(event: MouseEvent) {
      if (
        dropdownRef.current &&
        !dropdownRef.current.contains(event.target as Node)
      ) {
        setShowBusinessList(false);
      }
    }

    document.addEventListener("mousedown", handleClickOutside);

    return () => {
      document.removeEventListener("mousedown", handleClickOutside);
    };
  }, []);

  const passwordsMatch = password === confirmPassword;

  const passwordStrength =
    password.length < 8
      ? "Weak"
      : password.length < 12
        ? "Medium"
        : "Strong";

  const emailValid = email.includes("@") && email.includes(".");

  const formIsValid =
    businessName.trim() &&
    emailValid &&
    businessType &&
    password &&
    confirmPassword &&
    passwordsMatch;

  return (
    <main className="min-h-screen flex items-center justify-center bg-zinc-50">
      <div className="w-full max-w-md rounded-2xl border border-zinc-200 bg-white p-8 shadow-lg">
        <div className="flex justify-center transition-transform duration-300 hover:scale-105">
          <Logo />
        </div>

        <h1 className="mt-6 text-3xl font-bold text-black">
          Register Your Business
        </h1>

        <p className="mt-2 text-zinc-500">
          Let's create your Pulse workspace.
        </p>

        {successMessage && (
          <div className="mt-5 rounded-xl border border-green-200 bg-green-50 p-4 text-green-700">
            {successMessage}
          </div>
        )}

        {message && (
          <div className="mt-5 rounded-xl border border-red-200 bg-red-50 p-4 text-red-700">
            {message}
          </div>
        )}

        <form
          className="mt-8 space-y-5"
          onSubmit={async (e) => {
            e.preventDefault();

            setLoading(true);
            setMessage("");
            setSuccessMessage("");

            try {
              const response = await fetch("/api/signup", {
                method: "POST",
                headers: {
                  "Content-Type": "application/json",
                },
                body: JSON.stringify({
                  businessName,
                  email,
                  phone: tel,
                  businessType,
                  password,
                }),
              });

              const data = await response.json();

              console.log(data);

              if (data.success) {
                setSuccessMessage(
                  data.message || "Business created successfully!"
                );

                setBusinessName("");
                setEmail("");
                setTel("");
                setbusinessType("");
                setPassword("");
                setConfirmPassword("");
              } else {
                setMessage(
                  data.message || "Unable to create your account."
                );
              }
            } catch (error) {
              console.error("Signup error:", error);

              setMessage(
                "Something went wrong. Please try again."
              );
            } finally {
              setLoading(false);
            }
          }}
        >
          <input
            type="text"
            placeholder="Business Name"
            value={businessName}
            onChange={(e) => setBusinessName(e.target.value)}
            className="w-full rounded-lg border border-zinc-300 px-4 py-3 outline-none transition focus:border-black focus:ring-2 focus:ring-black/10"
          />

          <input
            type="email"
            placeholder="Email Address"
            value={email}
            onChange={(e) => setEmail(e.target.value)}
            className="w-full rounded-lg border border-zinc-300 px-4 py-3 outline-none transition focus:border-black focus:ring-2 focus:ring-black/10"
          />

          {email && !emailValid && (
            <p className="mt-2 text-sm text-red-500">
              Please enter a valid email address.
            </p>
          )}

          <input
            type="tel"
            placeholder="WhatsApp Number"
            value={tel}
            onChange={(e) => setTel(e.target.value)}
            className="w-full rounded-lg border border-zinc-300 px-4 py-3 outline-none transition focus:border-black focus:ring-2 focus:ring-black/10"
          />

          <div ref={dropdownRef} className="relative">
            <input
              type="text"
              placeholder="Business Type"
              value={businessType}
              onChange={(e) => {
                setbusinessType(e.target.value);
                setIsTypingBusiness(true);
                setShowBusinessList(true);
              }}
              onFocus={() => {
                setShowBusinessList(true);
              }}
              className="w-full rounded-lg border border-zinc-300 px-4 py-3 outline-none transition focus:border-black focus:ring-2 focus:ring-black/10"
            />

            {showBusinessList && (
              <div className="absolute left-0 right-0 z-10 mt-2 max-h-60 overflow-y-auto rounded-xl border border-zinc-300 bg-white shadow-lg">
                {businessTypes
                  .filter((type) => {
                    if (!isTypingBusiness) return true;

                    return type
                      .toLowerCase()
                      .includes(businessType.toLowerCase());
                  })
                  .map((type) => (
                    <div
                      key={type}
                      onClick={() => {
                        setbusinessType(type);
                        setShowBusinessList(false);
                        setIsTypingBusiness(false);
                      }}
                      className="cursor-pointer border-b border-zinc-100 px-4 py-3 transition-colors hover:bg-black hover:text-white"
                    >
                      {type}
                    </div>
                  ))}
              </div>
            )}
          </div>

          <div className="relative">
            <input
              type={showPassword ? "text" : "password"}
              placeholder="Password"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              className="w-full rounded-lg border border-zinc-300 px-4 py-3 pr-12 outline-none transition focus:border-black focus:ring-2 focus:ring-black/10"
            />

            <button
              type="button"
              onClick={() => setShowPassword(!showPassword)}
              className="absolute right-3 top-1/2 -translate-y-1/2 text-zinc-500 hover:text-black"
            >
              {showPassword ? (
                <EyeOff size={20} />
              ) : (
                <Eye size={20} />
              )}
            </button>
          </div>

          {password && (
            <p
              className={`text-sm ${
                passwordStrength === "Weak"
                  ? "text-red-500"
                  : passwordStrength === "Medium"
                    ? "text-yellow-500"
                    : "text-green-500"
              }`}
            >
              Password strength: {passwordStrength}
            </p>
          )}

          <div className="relative">
            <input
              type={showConfirmPassword ? "text" : "password"}
              placeholder="Confirm Password"
              value={confirmPassword}
              onChange={(e) => setConfirmPassword(e.target.value)}
              className="w-full rounded-lg border border-zinc-300 px-4 py-3 pr-12 outline-none transition focus:border-black focus:ring-2 focus:ring-black/10"
            />

            <button
              type="button"
              onClick={() =>
                setShowConfirmPassword(!showConfirmPassword)
              }
              className="absolute right-3 top-1/2 -translate-y-1/2 text-zinc-500 hover:text-black"
            >
              {showConfirmPassword ? (
                <EyeOff size={20} />
              ) : (
                <Eye size={20} />
              )}
            </button>
          </div>

          {confirmPassword && !passwordsMatch && (
            <p className="text-sm text-red-500">
              Passwords do not match.
import LogoutButton from "@/components/LogoutButton";
import { cookies } from "next/headers";
import { redirect } from "next/navigation";
import Link from "next/link";

import { prisma } from "@/lib/prisma";
import CreateWorkspaceForm from "@/components/CreateWorkspaceForm";

export default async function DashboardPage() {
  const cookieStore = await cookies();

  const businessId = cookieStore.get("businessId");

  if (!businessId) {
    redirect("/login");
  }

  const business = await prisma.business.findUnique({
    where: {
      id: businessId.value,
    },
  });

  if (!business) {
    redirect("/login");
  }

  const workspaces = await prisma.workspace.findMany({
    where: {
      businessId: business.id,
    },
    include: {
      projects: true,
    },
    orderBy: {
      createdAt: "desc",
    },
  });

  const projectCount = workspaces.reduce(
    (sum, workspace) => sum + workspace.projects.length,
    0
  );

  return (
    <main className="min-h-screen bg-gray-100 p-8">

      <div className="max-w-6xl mx-auto">

        <h1 className="text-4xl font-bold">
          👋 Welcome back,
        </h1>

        <p className="text-gray-600 mt-2 mb-8">
          {business.businessName}
        </p>

        <LogoutButton />

        <div className="grid md:grid-cols-3 gap-6 mb-10">

          <div className="bg-white rounded-2xl shadow p-6">
            <p className="text-gray-500">
              🏢 Workspaces
            </p>

            <h2 className="text-4xl font-bold mt-2">
              {workspaces.length}
            </h2>
          </div>

          <div className="bg-white rounded-2xl shadow p-6">
            <p className="text-gray-500">
              📁 Projects
            </p>

            <h2 className="text-4xl font-bold mt-2">
              {projectCount}
            </h2>
          </div>

          <div className="bg-white rounded-2xl shadow p-6">
            <p className="text-gray-500">
              📧 Email
            </p>

            <h2 className="font-semibold mt-2 break-all">
              {business.email}
            </h2>
          </div>

        </div>

        <div className="bg-white rounded-2xl shadow p-6 mb-10">

          <h2 className="text-2xl font-bold mb-6">
            Create Workspace
          </h2>

          <CreateWorkspaceForm />

        </div>

        <div className="bg-white rounded-2xl shadow p-6">

          <h2 className="text-2xl font-bold mb-6">
            Your Workspaces
          </h2>

          {workspaces.length === 0 ? (

            <p className="text-gray-500">
              No workspace yet.
            </p>

          ) : (

            <div className="grid md:grid-cols-2 gap-4">

              {workspaces.map((workspace) => (

                <Link
                  key={workspace.id}
                  href={`/workspace/${workspace.id}`}
                  className="border rounded-xl p-5 hover:bg-gray-50 transition"
                >

                  <h3 className="font-bold text-lg">
                    {workspace.name}
                  </h3>

                  <p className="text-gray-500 mt-2">
                    {workspace.description ||
                      "No description"}
                  </p>

                  <div className="mt-4 text-sm text-gray-400">

                    {workspace.projects.length} project
                    {workspace.projects.length !== 1
                      ? "s"
                      : ""}

                  </div>

                </Link>

              ))}

            </div>

          )}

        </div>

      </div>

    </main>
  );
}

