import { NextResponse } from "next/server";
import { prisma } from "@/lib/prisma";
import { getCurrentBusiness } from "@/lib/auth/business";

export async function PATCH(request: Request) {
  try {
    const business = await getCurrentBusiness();

    if (!business) {
      return NextResponse.json(
        {
          success: false,
          message: "Unauthorized.",
        },
        { status: 401 }
      );
    }

    const { taskId, status } = await request.json();

    if (!taskId || !status) {
      return NextResponse.json(
        {
          success: false,
          message: "Task ID and status are required.",
        },
        { status: 400 }
      );
    }

    const validStatuses = [
      "TODO",
      "IN_PROGRESS",
      "DONE",
    ];

    if (!validStatuses.includes(status)) {
      return NextResponse.json(
        {
          success: false,
          message: "Invalid task status.",
        },
        { status: 400 }
      );
    }

    const task = await prisma.$transaction(
      async (tx) => {
        const existingTask =
          await tx.task.findFirst({
            where: {
              id: taskId,
              project: {
                workspace: {
                  businessId: business.id,
                },
              },
            },
          });

        if (!existingTask) {
          throw new Error("Task not found.");
        }

        if (existingTask.status === status) {
          return existingTask;
        }

        const updatedTask =
          await tx.task.update({
            where: {
              id: taskId,
            },
            data: {
              status,
            },
          });

        await tx.taskActivity.create({
          data: {
            taskId: updatedTask.id,
            type: "STATUS_CHANGED",
            message: `Status changed from ${existingTask.status} to ${updatedTask.status}.`,
          },
        });

        return updatedTask;
      }
    );

    return NextResponse.json({
      success: true,
      task,
    });
  } catch (error) {
    console.error(
      "PATCH /api/tasks/update error:",
      error
    );

    return NextResponse.json(
      {
        success: false,
        message: "Failed to update task.",
      },
      { status: 500 }
    );
  }
}import { NextResponse } from "next/server";
import { prisma } from "@/lib/prisma";
import { getCurrentBusiness } from "@/lib/auth/business";

export async function PATCH(request: Request) {
  try {
    const business = await getCurrentBusiness();

    if (!business) {
      return NextResponse.json(
        {
          success: false,
          message: "Unauthorized.",
        },
        { status: 401 }
      );
    }

    const {
      taskId,
      title,
      description,
      priority,
      dueDate,
    } = await request.json();

    if (!taskId) {
      return NextResponse.json(
        {
          success: false,
          message: "Task ID is required.",
        },
        { status: 400 }
      );
    }

    const updatedTask = await prisma.$transaction(
      async (tx) => {
        const existingTask =
          await tx.task.findFirst({
            where: {
              id: taskId,
              project: {
                workspace: {
                  businessId: business.id,
                },
              },
            },
          });

        if (!existingTask) {
          throw new Error("Task not found.");
        }

        const newDueDate = dueDate
          ? new Date(dueDate)
          : null;

        const priorityChanged =
          priority &&
          priority !== existingTask.priority;

        const titleChanged =
          title !== existingTask.title;

        const descriptionChanged =
          description !==
          existingTask.description;

        const dueDateChanged =
          newDueDate?.getTime() !==
            existingTask.dueDate?.getTime() ||
          (newDueDate === null &&
            existingTask.dueDate !== null);

        const task = await tx.task.update({
          where: {
            id: taskId,
          },
          data: {
            title,
            description,
            priority,
            dueDate: newDueDate,
          },
        });

        if (priorityChanged) {
          await tx.taskActivity.create({
            data: {
              taskId: task.id,
              type: "PRIORITY_CHANGED",
              message: `Priority changed from ${existingTask.priority} to ${task.priority}.`,
            },
          });
        }

        if (
          titleChanged ||
          descriptionChanged ||
          dueDateChanged
        ) {
          await tx.taskActivity.create({
            data: {
              taskId: task.id,
              type: "UPDATED",
              message: "Task details were updated.",
            },
          });
        }

        return task;
      }
    );

    return NextResponse.json({
      success: true,
      task: updatedTask,
    });
  } catch (error) {
    console.error(
      "PATCH /api/tasks/edit error:",
      error
    );

    return NextResponse.json(
      {
        success: false,
        message: "Failed to update task.",
      },
      { status: 500 }
    );
  }
}import { NextResponse } from "next/server";
import { prisma } from "@/lib/prisma";
import { getCurrentBusiness } from "@/lib/auth/business";

export async function DELETE(request: Request) {
  try {
    const business = await getCurrentBusiness();

    if (!business) {
      return NextResponse.json(
        {
          success: false,
          message: "Unauthorized.",
        },
        { status: 401 }
      );
    }

    const { taskId } = await request.json();

    if (!taskId) {
      return NextResponse.json(
        {
          success: false,
          message: "Task ID is required.",
        },
        { status: 400 }
      );
    }

    const task = await prisma.task.findFirst({
      where: {
        id: taskId,
        project: {
          workspace: {
            businessId: business.id,
          },
        },
      },
    });

    if (!task) {
      return NextResponse.json(
        {
          success: false,
          message: "Task not found.",
        },
        { status: 404 }
      );
    }

    await prisma.task.delete({
      where: {
        id: taskId,
      },
    });

    return NextResponse.json({
      success: true,
    });
  } catch (error) {
    console.error(
      "DELETE /api/tasks/delete error:",
      error
    );

    return NextResponse.json(
      {
        success: false,
        message: "Failed to delete task.",
      },
      { status: 500 }
    );
  }
}import { NextResponse } from "next/server";
import { prisma } from "@/lib/prisma";
import { getCurrentBusiness } from "@/lib/auth/business";

interface RouteContext {
  params: Promise<{
    id: string;
  }>;
}

export async function GET(
  request: Request,
  { params }: RouteContext
) {
  try {
    const business = await getCurrentBusiness();

    if (!business) {
      return NextResponse.json(
        {
          success: false,
          message: "Unauthorized.",
        },
        { status: 401 }
      );
    }

    const { id } = await params;

    const task = await prisma.task.findFirst({
      where: {
        id,
        project: {
          workspace: {
            businessId: business.id,
          },
        },
      },
      include: {
        activities: {
          orderBy: {
            createdAt: "desc",
          },
        },
      },
    });

    if (!task) {
      return NextResponse.json(
        {
          success: false,
          message: "Task not found.",
        },
        { status: 404 }
      );
    }

    return NextResponse.json({
      success: true,
      activities: task.activities,
    });
  } catch (error) {
    console.error(
      "GET /api/tasks/[id]/activities error:",
      error
    );

    return NextResponse.json(
      {
        success: false,
        message: "Failed to load task activities.",
      },
      { status: 500 }
    );
  }
}

