    setTitle(task.title);
    setDescription(task.description ?? "");
    setPriority(task.priority);
    setDueDate(
      task.dueDate
        ? task.dueDate.toISOString().slice(0, 10)
        : ""
    );
  }, [task]);

  async function saveTask() {
    if (!title.trim()) {
      toast.error("Task title is required.");
      return;
