          data.message ||
            "Failed to update task."
        );
      }
    } catch (error) {
      console.error(
        "Task update failed:",
        error
      );

      setTaskList(tasks);
    }
  }

  return (
    <DndContext
      onDragEnd={handleDragEnd}
    >
      <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
        <KanbanColumn
          id="TODO"
          title="🟡 TODO"
          tasks={taskList.filter(
            (task) =>
              task.status === "TODO"
          )}
        />

        <KanbanColumn
          id="IN_PROGRESS"
          title="🔵 IN PROGRESS"
          tasks={taskList.filter(
            (task) =>
              task.status ===
              "IN_PROGRESS"
          )}
        />

        <KanbanColumn
          id="DONE"
          title="🟢 DONE"
          tasks={taskList.filter(
            (task) =>
              task.status === "DONE"
          )}
        />
      </div>
    </DndContext>
  );
}

