require("dotenv/config");
const { PrismaClient } = require("@prisma/client");
const prisma = new PrismaClient();
const query = (sql) => prisma.$queryRawUnsafe(sql);

async function run() {
  const names = "'Business','Workspace','Project','Task','TaskActivity','AIJob'";
  const out = {};

  out.migrations = await query(`
    SELECT migration_name, checksum, finished_at, applied_steps_count, rolled_back_at
    FROM "_prisma_migrations"
    ORDER BY started_at
  `);
  out.tables = await query(`
    SELECT table_name
    FROM information_schema.tables
    WHERE table_schema = 'public' AND table_name IN (${names})
    ORDER BY table_name
  `);
  out.columns = await query(`
    SELECT table_name, column_name, data_type, udt_name, is_nullable, column_default
    FROM information_schema.columns
    WHERE table_schema = 'public' AND table_name IN (${names})
    ORDER BY table_name, ordinal_position
  `);
  out.enums = await query(`
    SELECT t.typname AS enum_name, e.enumlabel AS value
    FROM pg_type t
    JOIN pg_enum e ON t.oid = e.enumtypid
    JOIN pg_namespace n ON n.oid = t.typnamespace
    WHERE n.nspname = 'public'
      AND t.typname IN ('TaskActivityType','TaskStatus','TaskPriority','AIJobType','AIJobStatus')
    ORDER BY t.typname, e.enumsortorder
  `);
  out.foreignKeys = await query(`
    SELECT c.conname AS constraint_name, r.relname AS table_name, pg_get_constraintdef(c.oid) AS definition
    FROM pg_constraint c
    JOIN pg_class r ON r.oid = c.conrelid
    JOIN pg_namespace n ON n.oid = r.relnamespace
    WHERE c.contype = 'f' AND n.nspname = 'public' AND r.relname IN (${names})
    ORDER BY r.relname, c.conname
  `);
  out.indexes = await query(`
    SELECT tablename, indexname, indexdef
    FROM pg_indexes
    WHERE schemaname = 'public' AND tablename IN (${names})
    ORDER BY tablename, indexname
  `);
  out.rowCounts = {};
  for (const name of ['Business', 'Workspace', 'Project', 'Task', 'TaskActivity', 'AIJob']) {
    if (out.tables.some((table) => table.table_name === name)) {
      out.rowCounts[name] = (await query(`SELECT COUNT(*)::int AS count FROM "${name}"`))[0].count;
    }
  }

  console.log(JSON.stringify(out, null, 2));
}

run()
  .catch((error) => {
    console.error(error.code || error.name, error.message);
    process.exitCode = 1;
  })
  .finally(() => prisma.$disconnect());
